mapper.select:
SELECT b.b_idx, b.p_idx, b.b_name, b.b_address, b.b_description, b.b_latitude, b.b_altitude, b.b_phone, b.b_file, b.b_active, b.b_sns, b.b_hours, b.b_notice, b.b_refund_policy, p.p_name, /* 편의 시설 요약 (Boolean) */ (SELECT IF(COUNT(*) > 0, 1, 0) FROM space s JOIN facilities f ON s.s_idx = f.s_idx WHERE s.b_idx = b.b_idx AND f.f_parking = 1) as fac_parking, (SELECT IF(COUNT(*) > 0, 1, 0) FROM space s JOIN facilities f ON s.s_idx = f.s_idx WHERE s.b_idx = b.b_idx AND f.f_hours24 = 1) as fac_hours24, (SELECT IF(COUNT(*) > 0, 1, 0) FROM space s JOIN facilities f ON s.s_idx = f.s_idx WHERE s.b_idx = b.b_idx AND f.f_pet = 1) as fac_pet, (SELECT IF(COUNT(*) > 0, 1, 0) FROM space s JOIN facilities f ON s.s_idx = f.s_idx WHERE s.b_idx = b.b_idx AND (f.f_desk = 1 OR f.f_wifi = 1)) as fac_wifi, (SELECT IF(COUNT(*) > 0, 1, 0) FROM space s JOIN facilities f ON s.s_idx = f.s_idx WHERE s.b_idx = b.b_idx AND (f.f_cafe = 1 OR f.f_coffee = 1)) as fac_coffee, (SELECT IF(COUNT(*) > 0, 1, 0) FROM space s JOIN facilities f ON s.s_idx = f.s_idx WHERE s.b_idx = b.b_idx AND (f.f_fax = 1 OR f.f_printer = 1)) as fac_printer, (SELECT IF(COUNT(*) > 0, 1, 0) FROM space s JOIN facilities f ON s.s_idx = f.s_idx WHERE s.b_idx = b.b_idx AND (f.f_storage = 1 OR f.f_locker = 1)) as fac_locker
, (6371 * acos(cos(radians(#{lat})) * cos(radians(b.b_latitude)) * cos(radians(b.b_altitude) - radians(#{lng})) + sin(radians(#{lat})) * sin(radians(b.b_latitude)))) AS distance
ORDER BY distance ASC, b.b_idx DESC
LIMIT #{size} OFFSET #{skip}
LIMIT #{size}
